register.signature:
fn register(
        &mut self,
        next: &Vec<usize>,
        from: &[usize],
        position: usize,
        swap: SwapCertificate,
        max_words: usize,
    ) -> Result<(), ContinuationError>

register.body:
{
        if !self.seen.contains(next) {
            if self.seen.len() >= max_words {
                return Err(ContinuationError::WorkLimit);
            }
            let next = Rc::new(next.clone());
            self.seen.insert(Rc::clone(&next));
            self.queue.push_back(next);
            self.tree.push(TraceLink {
                from: from.to_vec(),
                position,
                swap,
            });
        }
        Ok(())
    }

trace_admission.signature:
fn trace_admission(
    machine: &PartialDynamics,
    start: usize,
    word: &[usize],
    limits: TraceLimits,
) -> Result<usize, ContinuationError>

trace_admission.body:
{
    if word.len() > limits.max_word_len || limits.max_words == 0 {
        return Err(ContinuationError::WorkLimit);
    }
    if machine.run(start, word)?.is_none() {
        return Err(ContinuationError::CertificateMismatch);
    }
    machine
        .reports()
        .len()
        .checked_add(1)
        .and_then(|n| n.checked_mul(n))
        .ok_or(ContinuationError::WorkLimit)
}

admissible_swap.body:
{
    let s = machine
        .run(start, &word[..position])?
        .ok_or(ContinuationError::CertificateMismatch)?;
    let swap = machine.certify_swap(s, word[position], word[position + 1], pairs)?;
    let SwapOutcome::Independent { ab, ba } = swap.outcome else {
        return Ok(None);
    };
    if mode == ReplayMode::ExactState && ab != ba {
        return Ok(None);
    }
    Ok(Some(swap))
}

expand_word.body:
{
    let mut scratch = None;
    for position in 0..word.len().saturating_sub(1) {
        frontier.charge(limits.max_swap_checks)?;
        let Some(swap) = admissible_swap(machine, start, word, position, mode, pairs)? else {
            continue;
        };
        if word[position] == word[position + 1] {
            continue;
        }
        // One reusable scratch word per expansion; queue and seen share each
        // newly discovered word. Public owned tree/member outputs stay exact.
        let next = scratch.get_or_insert_with(|| word.to_vec());
        next.swap(position, position + 1);
        frontier.register(next, word, position, swap, limits.max_words)?;
        next.swap(position, position + 1);
    }
    Ok(())
}

trace_component.body:
{
        let pairs = trace_admission(self, start, word, limits)?;
        let mut frontier = TraceFrontier::new(word);
        while let Some(word) = frontier.queue.pop_front() {
            expand_word(self, start, &word, mode, pairs, limits, &mut frontier)?;
        }
        Ok(TraceComponent {
            start,
            word: word.to_vec(),
            mode,
            members: frontier.seen.into_iter().map(Rc::unwrap_or_clone).collect(),
            tree: frontier.tree,
        })
    }

